<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Reports</h1><p class="text-secondary mb-0">MVP operational reports with CSV export.</p></div></div>
<div class="card shadow-sm mb-3"><div class="card-body"><div class="row g-2"><div class="col-md-4"><select id="type" class="form-select"><option value="stock_summary">Stock Summary</option><option value="sales">Sales History</option><option value="receipts">Receipt History</option><option value="payments">Payment History</option><option value="expenses">Expense Report</option><option value="outstanding">Customer Outstanding</option><option value="customer_cylinders">Cylinders Held by Customer</option><option value="cash">Daily Cash</option></select></div><div class="col-md-2"><input id="from" type="date" class="form-control" value="<?=e($today)?>"></div><div class="col-md-2"><input id="to" type="date" class="form-control" value="<?=e($today)?>"></div><div class="col-md-2"><input id="party" class="form-control" placeholder="Party ID"></div><div class="col-md-2"><input id="counter" class="form-control" placeholder="Counter ID"></div></div><div class="mt-2"><button id="run" class="btn btn-primary">Run</button> <button id="export" class="btn btn-outline-secondary">Export CSV</button></div></div></div>
<div class="card shadow-sm"><div class="card-header" id="title">Report</div><div class="card-body"><div class="table-responsive"><table class="table table-sm"><thead id="head"></thead><tbody id="rows"></tbody></table></div></div></div>
<script>
$(function(){const b=<?=json_encode(url('/'))?>;function esc(v){return $('<div>').text(v??'').html();}function query(){return{type:$('#type').val(),from:$('#from').val(),to:$('#to').val(),party_id:$('#party').val(),counter_id:$('#counter').val()};}function run(){ $.getJSON(b+'reports/data',query(),r=>{if(!r.ok){alert(r.message);return;}$('#title').text(r.data.title);const x=$('#head').empty();const y=$('#rows').empty();(r.data.columns||[]).forEach(c=>x.append('<th>'+esc(c)+'</th>'));(r.data.rows||[]).forEach(row=>{let t='<tr>';(r.data.columns||[]).forEach(c=>t+='<td>'+esc(row[c])+'</td>');y.append(t+'</tr>');});}).fail(x=>alert(x.responseJSON?.message||'Report failed'));}$('#run').click(run);$('#export').click(()=>{const q=query();delete q.type;const qs=new URLSearchParams(Object.assign(q,{type:$('#type').val()})).toString();window.location=b+'reports/export?'+qs;});run();});
</script>